#include <iostream>
#include <string>

using namespace std;

int main(){
    int n, max;
    cin >> n >> max;

    int hungerPoints = 0;

    for (int i = 0; i < n; i++){
        string food;
        cin >> food;
        hungerPoints += food[0] - 'A' + 1;
    }

    string ans = hungerPoints <= max * 0.2 ? "starving..." :
                 hungerPoints <= max * 0.5 ? "Yes, please!" :
                 hungerPoints <= max * 0.85 ? "I wouldn't mind eating something." :
                 hungerPoints < max ? "Just a little bit." :
                 hungerPoints <= max * 1.15 ? "No thanks, I'm full." :
                 "BURSTING!!!";

    cout << ans << endl;
}
